 output.append({'group':name,'assigned_indices':list(range(lo,hi+1)),'archive_sha256':arc['sha256'],'finding':finding,'evidence':[{'name':x['name'],'sha256':x['sha256'],'snapshot':x.get('snapshot'),'line_count':len((P/x['snapshot']).read_text().splitlines()) if 'snapshot'in x else None} for x in matched],'attribution':'Stored, archive-co-resident claims only. Exact archive/member hashes verified; no cryptographic binding of a historical process to all source/dependency bytes and environment is asserted. No supplied execution credited.'})
